import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Wait... I can feel something wrong with these mocks already
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockCart = {
  items: [{ id: '1', name: 'Widget', price: 29.99 }],
  total: 29.99,
  clearCart: mockClearCart,
};

vi.mock('./CartContext', () => ({
  useCart: () => mockCart,
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment }),
}));

describe('Checkout Component', () => {
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
    mockCart.items = [{ id: '1', name: 'Widget', price: 29.99 }];
  });

  // The tests are going to fail here if we don't fill everything...
  const fillShippingForm = async () => {
    await user.type(screen.getByLabelText(/street address/i), '123 Main St');
    await user.type(screen.getByLabelText(/city/i), 'Springfield');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip code/i), '90210');
  };

  const fillPaymentForm = async () => {
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'John Doe');
  };

  describe('Happy Path - Complete Checkout Flow', () => {
    it('completes entire checkout process successfully', async () => {
      mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });
      const onComplete = vi.fn();
      render(<Checkout onComplete={onComplete} />);

      // Shipping step
      await fillShippingForm();
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await fillPaymentForm();
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/review your order/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      expect(await screen.findByText(/order confirmed/i)).toBeInTheDocument();
      expect(screen.getByText('ORD-12345')).toBeInTheDocument();
      expect(onComplete).toHaveBeenCalledWith('ORD-12345');
    });
  });

  describe('Form Validation', () => {
    it('shows error for empty street address', async () => {
      render(<Checkout />);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates ZIP code format', async () => {
      render(<Checkout />);
      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });

    it('accepts ZIP+4 format', async () => {
      render(<Checkout />);
      await fillShippingForm();
      await user.clear(screen.getByLabelText(/zip code/i));
      await user.type(screen.getByLabelText(/zip code/i), '90210-1234');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.queryByText(/valid zip code required/i)).not.toBeInTheDocument();
    });

    it('validates card number is 16 digits', async () => {
      render(<Checkout />);
      await fillShippingForm();
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      await user.type(screen.getByLabelText(/card number/i), '123');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      expect(screen.getByText(/valid 16-digit card number required/i)).toBeInTheDocument();
    });
  });

  describe('Edge Cases', () => {
    it('shows empty cart message when cart has no items', () => {
      mockCart.items = [];
      render(<Checkout onCancel={vi.fn()} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/your cart is empty/i);
      expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
    });

    it('handles payment failure and allows retry', async () => {
      mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
      render(<Checkout />);

      await fillShippingForm();
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));
      await fillPaymentForm();
      await user.click(screen.getByRole('button', { name: /review order/i }));
      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(await screen.findByText(/card declined/i)).toBeInTheDocument();

      // Retry succeeds
      mockProcessPayment.mockResolvedValue({ orderId: 'ORD-RETRY' });
      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(await screen.findByText(/order confirmed/i)).toBeInTheDocument();
    });
  });

  describe('Loading States', () => {
    it('disables buttons and shows loading during submission', async () => {
      mockProcessPayment.mockImplementation(() => new Promise(() => {}));
      render(<Checkout />);

      await fillShippingForm();
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));
      await fillPaymentForm();
      await user.click(screen.getByRole('button', { name: /review order/i }));
      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
      expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
    });
  });

  describe('Accessibility', () => {
    it('has no accessibility violations on shipping step', async () => {
      const { container } = render(<Checkout />);
      expect(await axe(container)).toHaveNoViolations();
    });

    it('announces errors to screen readers', async () => {
      render(<Checkout />);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      const alerts = screen.getAllByRole('alert');
      expect(alerts.length).toBeGreaterThan(0);
    });

    it('shows current step in progress indicator', () => {
      render(<Checkout />);
      const nav = screen.getByRole('navigation', { name: /checkout progress/i });
      const currentStep = within(nav).getByText('Shipping');

      expect(currentStep.closest('li')).toHaveAttribute('aria-current', 'step');
    });
  });
});
